"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[2962],{82962:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/the-therapist.png\\"\\n          title=\\"테라피스트\\"\\n          author=\\"B. A. 패리스\\"\\n          publisher=\\"모모\\"\\n          publishedDate=\\"2021-12-06\\"\\n          isbn=\\"9791191043518\\"\\n          rating=3.5\\n          tags=\\"thriller\\"\\n        />\\n</center>\\n\\n## Review\\n반전을 위해 복선을 잘 깔아 두었다.  \\n과거 사건을 두고 주인공이 누구도 믿지 못하고 의심한다.  \\n<br>\\n역시 많은 것을 알고 있는 인물은 의심과 질투를 많이 산다. ```심리상담가```는 쉽지 않은 직업임이 분명하다.  \\n<br>\\n과거 경찰이 놓친 사건을 주인공이 혼자서 해결한다는 그런 설정은 억지스럽지만, 이런 소설에는 어쩔 수 없는 것 같다. 주인공이 똑똑한 거라고 하자."}')}}]);